{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { normalizeDueDate } from './due-date.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec('CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
db.exec(`PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec(`BEGIN;
    ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
    UPDATE tasks SET position = id;
    COMMIT;`);
}
const projectQuery = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectQuery} ORDER BY p.id ASC`);
const findProject = db.prepare(`${projectQuery} WHERE p.id = ?`);
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position ASC, id ASC');
const findTask = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?))`);
const moveTask = db.prepare(`UPDATE tasks SET project_id = ?,
  position = (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?)
  WHERE project_id = ? AND id = ?`);
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskJSON = task => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/task-filters.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-filters.js', import.meta.url))]],
  ['/due-date.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./due-date.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJSON(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const server = http.createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') return json(response, 200, { status: 'ok' });
    if (request.method === 'GET' && pathname === '/api/projects') return json(response, 200, listProjects.all());
    const projectMatch = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = findProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (request.method === 'POST' && pathname === '/api/projects') {
      const input = await readJSON(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, findProject.get(result.lastInsertRowid));
    }
    if (request.method === 'PATCH' && projectMatch) {
      const projectId = projectMatch[1];
      if (!findProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
      const input = await readJSON(request);
      if (Object.hasOwn(input || {}, 'default_priority')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Default priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, projectId);
        return json(response, 200, findProject.get(projectId));
      }
      if (Object.hasOwn(input || {}, 'name')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectId);
        return json(response, 200, findProject.get(projectId));
      }
      if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archive state must be a boolean' });
      updateProject.run(Number(input.archived), projectId);
      return json(response, 200, findProject.get(projectId));
    }
    const tasksMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskJSON));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readJSON(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title, findProject.get(projectId).default_priority, projectId);
        return json(response, 201, taskJSON(findTask.get(projectId, result.lastInsertRowid)));
      }
      if (request.method === 'PATCH' && taskId) {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJSON(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (Object.hasOwn(input || {}, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === Number(projectId)) {
            return json(response, 400, { error: 'Choose another active destination project' });
          }
          const destination = findProject.get(destinationId);
          if (!destination) return json(response, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(response, 409, { error: 'Archived project' });
          moveTask.run(destinationId, destinationId, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(destinationId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'due_date')) {
          const date = normalizeDueDate(input.due_date);
          if (date === null) return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          setDueDate.run(date, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Unable to complete request' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { resolve } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

test('projects and tasks: validation, ownership, completion, rename, priority, archive, summaries, and restart persistence', async () => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp(resolve('data/test-'));
  // Start with the original schema to exercise all additive migrations.
  const legacy = new DatabaseSync(`${directory}/projects.sqlite`);
  legacy.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)));`);
  legacy.close();
  let child;
  let origin;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: `${directory}/projects.sqlite` },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    await new Promise((resolveReady, reject) => {
      let output = '';
      const timeout = setTimeout(() => reject(new Error('Server startup timed out')), 5000);
      child.once('exit', code => { clearTimeout(timeout); reject(new Error(`Server exited: ${code}`)); });
      child.once('error', error => { clearTimeout(timeout); reject(error); });
      child.stdout.on('data', chunk => {
        output += chunk;
        const match = output.match(/listening on port (\d+)/);
        if (match) { origin = `http://127.0.0.1:${match[1]}`; clearTimeout(timeout); resolveReady(); }
      });
    });
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = new Promise(resolveExit => child.once('exit', resolveExit));
      child.kill('SIGTERM');
      await exited;
    }
  }
  const get = path => fetch(`${origin}${path}`);
  const create = name => fetch(`${origin}/api/projects`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
  });
  const createTask = (projectId, title) => fetch(`${origin}/api/projects/${projectId}/tasks`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
  });
  const completeTask = (projectId, taskId, completed) => fetch(`${origin}/api/projects/${projectId}/tasks/${taskId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed }),
  });
  const renameTask = (projectId, taskId, title) => fetch(`${origin}/api/projects/${projectId}/tasks/${taskId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
  });
  const prioritizeTask = (projectId, taskId, priority) => fetch(`${origin}/api/projects/${projectId}/tasks/${taskId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority }),
  });
  const saveDueDate = (projectId, taskId, due_date) => fetch(`${origin}/api/projects/${projectId}/tasks/${taskId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ due_date }),
  });
  const moveTask = (projectId, taskId, destination_project_id) => fetch(`${origin}/api/projects/${projectId}/tasks/${taskId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ destination_project_id }),
  });
  const tasks = async projectId => (await get(`/api/projects/${projectId}/tasks`)).json();
  const archiveProject = (projectId, archived) => fetch(`${origin}/api/projects/${projectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived }),
  });
  const renameProject = (projectId, name) => fetch(`${origin}/api/projects/${projectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
  });
  const setDefault = (projectId, default_priority) => fetch(`${origin}/api/projects/${projectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ default_priority }),
  });
  try {
    await start();
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    for (const name of ['', ' \t\n ', null]) {
      const invalid = await create(name);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    assert.equal(first.archived, 0);
    assert.equal(first.default_priority, 'Normal');
    assert.equal(first.completed, 0);
    assert.equal(first.total, 0);
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`, '/app.js', '/task-filters.js', '/due-date.js', '/style.css']) {
      assert.equal((await get(path)).status, 200);
    }
    assert.equal((await get('/api/projects/999999')).status, 404);
    assert.deepEqual(await tasks(first.id), []);
    for (const title of ['', ' \t\n ', null]) {
      const invalid = await createTask(first.id, title);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await tasks(first.id), []);
    const taskResponse = await createTask(first.id, '  First task  ');
    assert.equal(taskResponse.status, 201);
    let firstTask = await taskResponse.json();
    assert.equal(firstTask.title, 'First task');
    assert.equal(firstTask.completed, false);
    assert.equal(firstTask.priority, 'Normal');
    assert.equal(firstTask.due_date, '');
    const secondTask = await (await createTask(first.id, 'Second task')).json();
    assert.equal(secondTask.priority, 'Normal');
    assert.ok(secondTask.id > firstTask.id);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.deepEqual(await tasks(second.id), []);
    const otherTask = await (await createTask(second.id, 'Other project task')).json();
    assert.deepEqual(await tasks(second.id), [otherTask]);
    assert.equal((await completeTask(second.id, firstTask.id, true)).status, 404);
    assert.equal((await completeTask(first.id, firstTask.id, 'true')).status, 400);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.equal((await createTask(999999, 'Missing project')).status, 404);
    assert.equal((await get('/api/projects/999999/tasks')).status, 404);
    const completedResponse = await completeTask(first.id, firstTask.id, true);
    assert.equal(completedResponse.status, 200);
    firstTask = await completedResponse.json();
    assert.equal(firstTask.completed, true);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    Object.assign(first, { total: 2, completed: 1 });
    Object.assign(second, { total: 1 });
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    // Date edits preserve ownership, order, completion, priority, and summaries.
    assert.equal((await saveDueDate(second.id, firstTask.id, '2024-02-29')).status, 404);
    const dated = await saveDueDate(first.id, firstTask.id, ' \t2024-02-29\n ');
    assert.equal(dated.status, 200);
    firstTask.due_date = '2024-02-29';
    assert.deepEqual(await dated.json(), firstTask);
    for (const invalid of ['2025-02-29', '1900-02-29', '2026-04-31', '0000-01-01', '2026-1-01', null]) {
      const response = await saveDueDate(first.id, firstTask.id, invalid);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Due date must be a valid YYYY-MM-DD date' });
      assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    }
    assert.deepEqual(await tasks(second.id), [otherTask]);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    for (const priority of ['', 'high', 'Urgent', null, 1]) {
      assert.equal((await prioritizeTask(first.id, firstTask.id, priority)).status, 400);
      assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    }
    assert.equal((await prioritizeTask(second.id, firstTask.id, 'High')).status, 404);
    for (const priority of ['Low', 'Normal', 'High']) {
      const response = await prioritizeTask(first.id, firstTask.id, priority);
      assert.equal(response.status, 200);
      firstTask.priority = priority;
      assert.deepEqual(await response.json(), firstTask);
      assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
      assert.deepEqual(await tasks(second.id), [otherTask]);
      assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    }
    for (const title of ['', ' \t\n ', null, 123]) {
      const invalid = await renameTask(first.id, firstTask.id, title);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Task title is required' });
      assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    }
    assert.equal((await renameTask(second.id, firstTask.id, 'Wrong project')).status, 404);
    assert.equal((await renameTask(first.id, 999999, 'Missing task')).status, 404);
    assert.equal((await renameTask(999999, firstTask.id, 'Missing project')).status, 404);
    const renamedTaskResponse = await renameTask(first.id, firstTask.id, '  Renamed completed task  ');
    assert.equal(renamedTaskResponse.status, 200);
    firstTask.title = 'Renamed completed task';
    assert.deepEqual(await renamedTaskResponse.json(), firstTask);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.deepEqual(await tasks(second.id), [otherTask]);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    for (const name of ['', ' \t\n ', null]) {
      const invalid = await renameProject(first.id, name);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Project name is required' });
      assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    }
    assert.equal((await renameProject(999999, 'Missing project')).status, 404);
    const renamedResponse = await renameProject(first.id, '  Renamed project  ');
    assert.equal(renamedResponse.status, 200);
    first.name = 'Renamed project';
    assert.deepEqual(await renamedResponse.json(), first);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    await stop();
    await start();
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.equal((await archiveProject(first.id, 'true')).status, 400);
    assert.equal((await archiveProject(999999, true)).status, 404);
    const archivedResponse = await archiveProject(first.id, true);
    assert.equal(archivedResponse.status, 200);
    first.archived = 1;
    assert.deepEqual(await archivedResponse.json(), first);
    assert.equal((await renameProject(first.id, 'Blocked rename')).status, 409);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.equal((await createTask(first.id, 'Blocked task')).status, 409);
    assert.equal((await completeTask(first.id, firstTask.id, false)).status, 409);
    assert.equal((await renameTask(first.id, firstTask.id, 'Blocked task rename')).status, 409);
    assert.equal((await prioritizeTask(first.id, firstTask.id, 'Low')).status, 409);
    assert.equal((await saveDueDate(first.id, firstTask.id, '')).status, 409);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    await stop();
    await start();
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${second.id}`)).json(), second);
    assert.equal((await get(`/projects/${first.id}`)).status, 200);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.deepEqual(await tasks(second.id), [otherTask]);
    assert.equal((await createTask(first.id, 'Still blocked after restart')).status, 409);
    assert.equal((await renameProject(first.id, 'Still blocked rename')).status, 409);
    assert.equal((await renameTask(first.id, firstTask.id, 'Still blocked task rename')).status, 409);
    assert.equal((await prioritizeTask(first.id, firstTask.id, 'Normal')).status, 409);
    assert.equal((await saveDueDate(first.id, firstTask.id, '9999-12-31')).status, 409);
    const restoredResponse = await archiveProject(first.id, false);
    assert.equal(restoredResponse.status, 200);
    first.archived = 0;
    assert.deepEqual(await restoredResponse.json(), first);
    const restoredRename = await renameProject(first.id, '  Restored project  ');
    assert.equal(restoredRename.status, 200);
    first.name = 'Restored project';
    assert.deepEqual(await restoredRename.json(), first);
    const restoredTaskRename = await renameTask(first.id, firstTask.id, '  Restored task  ');
    assert.equal(restoredTaskRename.status, 200);
    firstTask.title = 'Restored task';
    assert.deepEqual(await restoredTaskRename.json(), firstTask);
    const restoredPriority = await prioritizeTask(first.id, secondTask.id, 'Low');
    assert.equal(restoredPriority.status, 200);
    secondTask.priority = 'Low';
    assert.deepEqual(await restoredPriority.json(), secondTask);
    const openTaskRename = await renameTask(first.id, secondTask.id, '  Renamed open task  ');
    assert.equal(openTaskRename.status, 200);
    secondTask.title = 'Renamed open task';
    assert.deepEqual(await openTaskRename.json(), secondTask);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    const reopenedResponse = await completeTask(first.id, firstTask.id, false);
    assert.equal(reopenedResponse.status, 200);
    firstTask = await reopenedResponse.json();
    assert.equal(firstTask.completed, false);
    first.completed = 0;
    await stop();
    await start();
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    const thirdTask = await (await createTask(first.id, 'Third task')).json();
    assert.equal(thirdTask.priority, 'Normal');
    assert.ok(thirdTask.id > otherTask.id);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask, thirdTask]);
    const third = await (await create('Third project')).json();
    assert.ok(third.id > second.id);
    assert.equal(third.default_priority, 'Normal');

    // Defaults affect only later creations in their own project.
    first.total = 3;
    const savedTasks = [firstTask, secondTask, thirdTask];
    for (const invalid of ['', 'high', 'Urgent', null, 1]) {
      assert.equal((await setDefault(first.id, invalid)).status, 400);
      assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
      assert.deepEqual(await tasks(first.id), savedTasks);
    }
    assert.equal((await setDefault(999999, 'High')).status, 404);
    for (const priority of ['Low', 'Normal', 'High']) {
      const response = await setDefault(first.id, priority);
      assert.equal(response.status, 200);
      first.default_priority = priority;
      assert.deepEqual(await response.json(), first);
      assert.deepEqual(await tasks(first.id), savedTasks);
      assert.deepEqual(await tasks(second.id), [otherTask]);
      assert.deepEqual(await (await get(`/api/projects/${second.id}`)).json(), second);
      const inherited = await (await createTask(first.id, `Inherited ${priority}`)).json();
      assert.equal(inherited.priority, priority);
      assert.equal(inherited.completed, false);
      assert.ok(inherited.id > savedTasks.at(-1).id);
      savedTasks.push(inherited);
      first.total++;
    }
    assert.deepEqual(await tasks(first.id), savedTasks);
    assert.equal((await setDefault(second.id, 'Low')).status, 200);
    second.default_priority = 'Low';
    const otherInherited = await (await createTask(second.id, 'Independent default')).json();
    assert.equal(otherInherited.priority, 'Low');
    second.total++;
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited]);
    assert.deepEqual(await tasks(first.id), savedTasks);
    assert.equal((await renameProject(first.id, 'Default retained')).status, 200);
    first.name = 'Default retained';
    assert.equal((await archiveProject(first.id, true)).status, 200);
    first.archived = 1;
    assert.equal((await setDefault(first.id, 'Normal')).status, 409);
    await stop();
    await start();
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);
    assert.deepEqual(await tasks(first.id), savedTasks);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited]);
    assert.equal((await setDefault(first.id, 'Low')).status, 409);
    assert.equal((await archiveProject(first.id, false)).status, 200);
    first.archived = 0;
    const afterRestore = await (await createTask(first.id, 'After restore')).json();
    assert.equal(afterRestore.priority, 'High');
    savedTasks.push(afterRestore);
    first.total++;
    assert.equal((await setDefault(first.id, 'Low')).status, 200);
    first.default_priority = 'Low';
    await stop();
    await start();
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);
    assert.deepEqual(await tasks(first.id), savedTasks);
    const afterRestart = await (await createTask(first.id, 'After restart')).json();
    assert.equal(afterRestart.priority, 'Low');
    assert.equal(afterRestart.due_date, '');
    // Restoration permits clearing; clearing and independent dates survive restart.
    assert.equal((await saveDueDate(first.id, firstTask.id, ' \t\n ')).status, 200);
    firstTask.due_date = '';
    assert.equal((await saveDueDate(first.id, secondTask.id, '0001-01-01')).status, 200);
    secondTask.due_date = '0001-01-01';
    savedTasks.push(afterRestart);
    first.total++;
    await stop();
    await start();
    assert.deepEqual(await tasks(first.id), savedTasks);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited]);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);

    // Moving an older task appends it, preserving every saved field and identity.
    assert.equal((await completeTask(first.id, firstTask.id, true)).status, 200);
    firstTask.completed = true;
    assert.equal((await saveDueDate(first.id, firstTask.id, '2028-02-29')).status, 200);
    firstTask.due_date = '2028-02-29';
    assert.equal((await setDefault(second.id, 'Normal')).status, 200);
    second.default_priority = 'Normal';
    for (const invalid of [first.id, 0, -1, null, '2', 1.5]) {
      assert.equal((await moveTask(first.id, firstTask.id, invalid)).status, 400);
    }
    assert.equal((await moveTask(first.id, firstTask.id, 999999)).status, 404);
    assert.equal((await moveTask(second.id, firstTask.id, first.id)).status, 404);
    assert.equal((await archiveProject(second.id, true)).status, 200);
    assert.equal((await moveTask(first.id, firstTask.id, second.id)).status, 409);
    assert.equal((await archiveProject(first.id, true)).status, 200);
    assert.equal((await moveTask(first.id, firstTask.id, third.id)).status, 409);
    assert.deepEqual(await tasks(first.id), savedTasks);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited]);
    assert.equal((await archiveProject(first.id, false)).status, 200);
    assert.equal((await archiveProject(second.id, false)).status, 200);
    const moved = await moveTask(first.id, firstTask.id, second.id);
    assert.equal(moved.status, 200);
    assert.deepEqual(await moved.json(), firstTask);
    const remaining = savedTasks.filter(task => task.id !== firstTask.id);
    assert.deepEqual(await tasks(first.id), remaining);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited, firstTask]);
    first.total--;
    second.total++;
    second.completed = 1;
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);
    assert.equal((await renameTask(first.id, firstTask.id, 'Wrong owner')).status, 404);
    const laterTask = await (await createTask(second.id, 'Created after move')).json();
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited, firstTask, laterTask]);
    second.total++;
    await stop();
    await start();
    assert.deepEqual(await tasks(first.id), remaining);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited, firstTask, laterTask]);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);
    // A second move appends again; blank due dates also travel unchanged.
    assert.equal((await moveTask(second.id, firstTask.id, first.id)).status, 200);
    assert.equal((await moveTask(first.id, afterRestart.id, third.id)).status, 200);
    const finalFirst = remaining.filter(task => task.id !== afterRestart.id).concat(firstTask);
    assert.deepEqual(await tasks(first.id), finalFirst);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited, laterTask]);
    assert.deepEqual(await tasks(third.id), [afterRestart]);
    first.completed = 1;
    second.total--;
    second.completed = 0;
    third.total = 1;
    await stop();
    await start();
    assert.deepEqual(await tasks(first.id), finalFirst);
    assert.deepEqual(await tasks(second.id), [otherTask, otherInherited, laterTask]);
    assert.deepEqual(await tasks(third.id), [afterRestart]);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second, third]);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('migration preserves existing project IDs, tasks, and completion state', async () => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp(resolve('data/migration-'));
  const dbPath = `${directory}/legacy.sqlite`;
  const legacy = new DatabaseSync(dbPath);
  legacy.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)));
    INSERT INTO projects VALUES (42, 'Existing project');
    INSERT INTO tasks VALUES (71, 42, 'Existing completed task', 1);
    INSERT INTO tasks VALUES (72, 42, 'Existing open task', 0);`);
  legacy.close();
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath }, stdio: ['ignore', 'pipe', 'pipe'],
  });
  try {
    const origin = await new Promise((resolveReady, reject) => {
      let output = '';
      const timeout = setTimeout(() => reject(new Error('Server startup timed out')), 5000);
      child.once('error', error => { clearTimeout(timeout); reject(error); });
      child.once('exit', code => { clearTimeout(timeout); reject(new Error(`Server exited: ${code}`)); });
      child.stdout.on('data', chunk => {
        output += chunk;
        const match = output.match(/listening on port (\d+)/);
        if (match) { clearTimeout(timeout); resolveReady(`http://127.0.0.1:${match[1]}`); }
      });
    });
    assert.deepEqual(await (await fetch(`${origin}/api/projects`)).json(), [
      { id: 42, name: 'Existing project', archived: 0, default_priority: 'Normal', total: 2, completed: 1 },
    ]);
    assert.deepEqual(await (await fetch(`${origin}/api/projects/42/tasks`)).json(), [
      { id: 71, title: 'Existing completed task', completed: true, priority: 'Normal', due_date: '' },
      { id: 72, title: 'Existing open task', completed: false, priority: 'Normal', due_date: '' },
    ]);
  } finally {
    if (child.exitCode === null) {
      const exited = new Promise(resolveExit => child.once('exit', resolveExit));
      child.kill('SIGTERM');
      await exited;
    }
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. No dependencies need installation.

Start with `npm start`. The server binds to `0.0.0.0` on `PORT` (default `8080`).
Set `DB_PATH` to select a persistent SQLite file (default `data/workboard.sqlite`).

Example: `PORT=8080 DB_PATH=data/workboard.sqlite npm start`

Run verification with `npm test`.

Create projects on the home page and open a project to create tasks. Task titles
are trimmed, tasks start open, and the Task filter shows All, Open, or Completed
tasks in creation order. Completion changes and project ownership are stored in
the configured SQLite file and survive restarts.

Projects can be archived and restored from the project list, which shows each
project's completion summary. Archived projects keep their tasks and allow
filtering, but task creation, completion changes, and renaming are disabled.
Use New project name and Rename project on an active project page to rename it.
Names are trimmed and required; renaming preserves the URL, creation order,
tasks, and completion summary and persists across restarts.

Each task row provides New task title and Rename task. Renaming trims and
requires a title while preserving ownership, order, completion, and summaries.
Task renaming persists across restarts and is disabled in archived projects.

Task priority is saved independently for each task and can
be changed to Low or High. Archived projects disable priority edits.
The Priority filter (All, Low, Normal, High) combines with the Task filter;
both initially show All and remain usable in archived projects. Matching tasks
keep their creation order. Edits immediately update matching rows while keeping
both filter selections, and project summaries always count every task.

Default task priority on each project page selects Low, Normal, or High for
subsequent new tasks. Projects initially default to Normal. Changing the default
preserves existing tasks and both filter selections. Defaults are independent
per project, persist across restarts, renaming, archive and restore, and cannot
be edited while the project is archived.

Each task has an optional Task due date, saved with Save due date. Dates must be
real Gregorian calendar dates in YYYY-MM-DD format (years 0001–9999). Surrounding
whitespace is trimmed; an empty value clears the date. Invalid dates show an
alert and leave saved data unchanged. Dates persist across restarts and task
renames without changing filters or summaries. Archived projects disable date
editing; restoration preserves dates and enables editing again.

Due from and Due through apply an inclusive due-date range alongside both task
filters. Empty boundaries are unbounded; tasks without dates match only when
both boundaries are empty. Apply due range validates and trims dates, retaining
the previous applied range if a date is invalid or the boundaries are reversed.
Task edits re-evaluate all filters without resetting them. Range controls remain
usable in archived projects, and reopening a project starts with an empty range.
